package synctechsms

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"io"
	"os"
	"path/filepath"
	"testing"
	"time"

	Assert "github.com/stretchr/testify/assert"   //nolint:importas // Keep the package constructor available beside local helpers.
	Require "github.com/stretchr/testify/require" //nolint:importas // Keep the package constructor available beside local helpers.
	"go.kenn.io/msgvault/internal/store"
	"go.kenn.io/msgvault/internal/testutil"
)

// Generated by the unchanged native importer and schema at
// 8799dfacec52b3a71849b6776ba864863cd69537, using only reserved synthetic phones.
// The original archive has no import-run, decision or retained identity table.
//
//go:embed testdata/import-original-native-8799.sqlite.gz
var originalNativeSynctechArchive []byte

func TestImportSynctechOriginalNativeArchiveUpgradeRetainsLogicalIdentity(t *testing.T) {
	testutil.SkipIfPostgres(t, "this is a real native SQLite archive upgrade fixture")
	for _, boundary := range []string{"capture", "delete-before-capture"} {
		t.Run(boundary, func(t *testing.T) {
			assert := Assert.New(t)

			require := Require.New(t)

			st := openOriginalNativeSynctechArchive(t)
			var messageID, remoteID int64
			var oldKey string
			require.NoError(st.DB().QueryRow(`SELECT id,source_message_id FROM messages`).Scan(&messageID, &oldKey))
			require.NoError(st.DB().QueryRow(st.Rebind(`SELECT participant_id FROM participant_identifiers WHERE identifier_type=? AND identifier_value=?`), ParticipantIdentifierType, "+15550000002").Scan(&remoteID))
			survivor, err := st.EnsureParticipantByPhone("+15550000003", "Synthetic Survivor", ParticipantIdentifierType)
			require.NoError(err)
			require.NoError(st.MergeParticipants(remoteID, survivor))
			if boundary == "delete-before-capture" {
				_, err = st.DB().Exec(st.Rebind(`UPDATE messages SET deleted_at=?,delete_batch_id=? WHERE id=?`), time.Now().UTC(), "synthetic-original-synctech-delete", messageID)
				require.NoError(err)
				deleted, err := st.DeleteDedupedBatchContext(t.Context(), "synthetic-original-synctech-delete")
				require.NoError(err)
				require.Equal(int64(1), deleted)
			}
			configureSyntheticSynctechImport(t, st, true)
			var runs, events int
			require.NoError(st.DB().QueryRow(`SELECT COUNT(*) FROM import_runs`).Scan(&runs))
			assert.Zero(runs, "cutover cannot invent a historical import run")
			directory := t.TempDir()
			backup := filepath.Join(directory, "messages.xml")
			require.NoError(os.WriteFile(backup, []byte(`<smses count="1"><mms date="1717214460000" msg_box="1" m_id="synthetic-original-mms"><parts><part seq="0" ct="text/plain" text="Synthetic original native MMS" /></parts><addrs><addr address="+15550000002" type="137" /><addr address="+15550000001" type="151" /></addrs></mms></smses>`), 0o600))
			summary, err := NewImporter(st, ImportOptions{OwnerPhone: "+15550000001", IncludeMMS: true, NotifyImports: true}).ImportPath(backup)
			require.NoError(err)
			require.Len(summary.MessageIDs, 1)
			require.NotEmpty(summary.ImportRunID)
			var newKey, body string
			require.NoError(st.DB().QueryRow(st.Rebind(`SELECT source_message_id FROM messages WHERE id=?`), summary.MessageIDs[0]).Scan(&newKey))
			assert.NotEqual(oldKey, newKey, "preserve native participant-ID-dependent archive keys")
			require.NoError(st.DB().QueryRow(st.Rebind(`SELECT body_text FROM message_bodies WHERE message_id=?`), summary.MessageIDs[0]).Scan(&body))
			assert.Equal("Synthetic original native MMS", body)
			require.NoError(st.DB().QueryRow(`SELECT COUNT(*) FROM mcp_event_log WHERE family='msgvault.import_message_archived'`).Scan(&events))
			assert.Zero(events, "upgrade must not replay a logical MMS from the original native archive")
		})
	}
}

func openOriginalNativeSynctechArchive(t *testing.T) *store.Store {
	t.Helper()
	testutil.SkipIfPostgres(t, "this is a real native SQLite archive fixture")
	reader, err := gzip.NewReader(bytes.NewReader(originalNativeSynctechArchive))
	Require.NoError(t, err)
	contents, err := io.ReadAll(reader)
	Require.NoError(t, err)
	Require.NoError(t, reader.Close())
	path := filepath.Join(t.TempDir(), "archive.sqlite")
	Require.NoError(t, os.WriteFile(path, contents, 0o600))
	st, err := store.OpenForTest(path)
	Require.NoError(t, err)
	t.Cleanup(func() { Require.NoError(t, st.Close()) })
	Require.NoError(t, st.InitSchema())
	return st
}
